# -*- coding: utf-8 -*-
"""
Lightweight Mess System Updater for PythonAnywhere
Updates:
- Mess Scan local time & rich audit cards
- Duplicate scan dual preservation (alert + original record)
- Dedicated Mess User Login (/mess/login/)
- Mess Claim Pass & Mobile responsive UX
"""
import os
import sys
import base64
import zlib
import subprocess

FILES = {'portal/urls.py': '', 'portal/views.py': '', 'templates/mess_login.html': '', 'templates/mess_scan.html': '', 'templates/mess_claim_pass.html': '', 'templates/mess_user.html': '', 'templates/mess_monitor.html': '', 'templates/mess_kitchen.html': '', 'templates/camp_gate.html': '', 'templates/login.html': ''}

def main():
    print("=" * 60)
    print("🚀 APPLYING MESS MODULE UPDATES TO SERVER...")
    print("=" * 60)

    base_dir = os.path.dirname(os.path.abspath(__file__))

    for rel_path, enc_data in FILES.items():
        dest_path = os.path.join(base_dir, rel_path.replace('/', os.sep))
        os.makedirs(os.path.dirname(dest_path), exist_ok=True)
        compressed = base64.b64decode(enc_data.encode('ascii'))
        content = zlib.decompress(compressed)
        with open(dest_path, 'wb') as f:
            f.write(content)
        print(f"  ✓ Updated: {rel_path} ({len(content)} bytes)")

    print("-" * 60)
    print("Running database migrations (just in case)...")
    python_bin = sys.executable
    manage_py = os.path.join(base_dir, 'manage.py')
    if os.path.exists(manage_py):
        subprocess.run([python_bin, manage_py, 'migrate', '--noinput'])

    print("=" * 60)
    print("✅ MESS SYSTEM UPDATES APPLIED SUCCESSFULLY!")
    print("NOTE: Existing database records (punches, employees) were 100% PRESERVED!")
    print("=" * 60)

if __name__ == '__main__':
    main()
